def peek_safetensors(path, max_keys=5):
    print(f"\n=== peek {path} ===")
    try:
        print("filesize:", os.path.getsize(path))
        with open(path,"rb") as f:
            hlen_bytes=f.read(8)
            if len(hlen_bytes)<8:
                print("too short"); return
            hlen=struct.unpack("<Q", hlen_bytes)[0]
            print("header_len:", hlen)
            hjson=f.read(hlen)
            # header may be large (~ few KB), safe to parse
            hj=json.loads(hjson)
            # __metadata__ plus tensors
